describe('File Upload - File Name and Size Display', () => {
  beforeEach(() => {
    cy.visit('http://localhost:3000');
    cy.get('input[type="file"]').as('fileInput');
  });

  it('should display file name and size after selecting a file', () => {
    const fileName = 'test-document.pdf';
    const fileSize = '2048';

    cy.fixture('files/test-document.pdf', 'binary')
      .then(fileContent => Cypress.Blob.binaryStringToBlob(fileContent))
      .then(blob => {
        const file = new File([blob], fileName, { type: 'application/pdf' });
        const dataTransfer = new DataTransfer();
        dataTransfer.items.add(file);

        cy.get('@fileInput').then(input => {
          input[0].files = dataTransfer.files;
          cy.get('@fileInput').trigger('change', { force: true });
        });
      });

    cy.get('[data-testid="file-name"]').should('be.visible');
    cy.get('[data-testid="file-name"]').should('contain', fileName);
    cy.get('[data-testid="file-size"]').should('be.visible');
    cy.get('[data-testid="file-size"]').should('contain', 'KB');
  });

  it('should display correct file size in appropriate unit (KB, MB)', () => {
    const largeFileName = 'large-file.zip';

    cy.fixture('files/large-file.zip', 'binary')
      .then(fileContent => Cypress.Blob.binaryStringToBlob(fileContent))
      .then(blob => {
        const file = new File([blob], largeFileName, { type: 'application/zip' });
        const dataTransfer = new DataTransfer();
        dataTransfer.items.add(file);

        cy.get('@fileInput').then(input => {
          input[0].files = dataTransfer.files;
          cy.get('@fileInput').trigger('change', { force: true });
        });
      });

    cy.get('[data-testid="file-name"]').should('contain', largeFileName);
    cy.get('[data-testid="file-size"]').then($element => {
      const sizeText = $element.text();
      expect(sizeText).to.match(/^\d+(\.\d+)?\s(B|KB|MB|GB)$/);
    });
  });

  it('should handle multiple file selections and display each file name and size', () => {
    const files = [
      { name: 'document1.pdf', type: 'application/pdf' },
      { name: 'document2.docx', type: 'application/vnd.openxmlformats-officedocument.wordprocessingml.document' }
    ];

    const dataTransfer = new DataTransfer();

    cy.fixture('files/test-document.pdf', 'binary')
      .then(fileContent => Cypress.Blob.binaryStringToBlob(fileContent))
      .then(blob => {
        const file1 = new File([blob], files[0].name, { type: files[0].type });
        dataTransfer.items.add(file1);

        return cy.fixture('files/test-document.pdf', 'binary');
      })
      .then(fileContent => Cypress.Blob.binaryStringToBlob(fileContent))
      .then(blob => {
        const file2 = new File([blob], files[1].name, { type: files[1].type });
        dataTransfer.items.add(file2);

        cy.get('@fileInput').then(input => {
          input[0].files = dataTransfer.files;
          cy.get('@fileInput').trigger('change', { force: true });
        });
      });

    cy.get('[data-testid="file-list-item"]').should('have.length', 2);
    cy.get('[data-testid="file-list-item"]').first().within(() => {
      cy.get('[data-testid="file-name"]').should('contain', files[0].name);
      cy.get('[data-testid="file-size"]').should('be.visible');
    });
    cy.get('[data-testid="file-list-item"]').last().within(() => {
      cy.get('[data-testid="file-name"]').should('contain', files[1].name);
      cy.get('[data-testid="file-size"]').should('be.visible');
    });
  });

  it('should update file name and size when a different file is selected', () => {
    const firstFile = 'initial-file.txt';
    const secondFile = 'replacement-file.pdf';

    cy.fixture('files/test-document.pdf', 'binary')
      .then(fileContent => Cypress.Blob.binaryStringToBlob(fileContent))
      .then(blob => {
        const file = new File([blob], firstFile, { type: 'text/plain' });
        const dataTransfer = new DataTransfer();
        dataTransfer.items.add(file);

        cy.get('@fileInput').then(input => {
          input[0].files = dataTransfer.files;
          cy.get('@fileInput').trigger('change', { force: true });
        });
      });

    cy.get('[data-testid="file-name"]').should('contain', firstFile);

    cy.fixture('files/test-document.pdf', 'binary')
      .then(fileContent => Cypress.Blob.binaryStringToBlob(fileContent))
      .then(blob => {
        const file = new File([blob], secondFile, { type: 'application/pdf' });
        const dataTransfer = new DataTransfer();
        dataTransfer.items.add(file);

        cy.get('@fileInput').then(input => {
          input[0].files = dataTransfer.files;
          cy.get('@fileInput').trigger('change', { force: true });
        });
      });

    cy.get('[data-testid="file-name"]').should('contain', secondFile);
    cy.get('[data-testid="file-name"]').should('not.contain', firstFile);
  });

  it('should handle edge case of very small file size display', () => {
    const tinyFileName = 'tiny.txt';

    cy.get('@fileInput').then(input => {
      const blob = new Blob(['a'], { type: 'text/plain' });
      const file = new File([blob], tinyFileName, { type: 'text/plain' });
      const dataTransfer = new DataTransfer();
      dataTransfer.items.add(file);

      input[0].files = dataTransfer.files;
      cy.get('@fileInput').trigger('change', { force: true });
    });

    cy.get('[data-testid="file-name"]').should('contain', tinyFileName);
    cy.get('[data-testid="file-size"]').should('contain', 'B');
  });
});
